def post_stock(stock):
    payload = json.dumps(stock, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(API_URL, data=payload, headers={
        'Content-Type': 'application/json; charset=utf-8'
    }, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            result = json.loads(resp.read().decode('utf-8'))
            return True, result
    except urllib.error.HTTPError as e:
        return False, {"status": e.code, "msg": e.read().decode('utf-8', errors='replace')}
    except Exception as e:
        return False, {"error": str(e)}

TOTAL = len(STOCKS_DATA)
success_count = 0
fail_count = 0
results = []

for i, stock in enumerate(STOCKS_DATA, 1):
    code = stock['code']
    name = stock['data'].get('BaseInfo', {}).get('Name', '?')
    open_status = stock['data'].get('BaseInfo', {}).get('OpenStatus', '?')
    
    ok, result = post_stock(stock)
    status = 'OK' if ok and result.get('success') else 'FAIL'
    
    if ok and result.get('success'):
        success_count += 1
    else:
        fail_count += 1
    
    # Check data completeness
    data = stock['data']
    sections = []
    for key in ['HQInfo', 'ExtInfo', 'ProInfo', 'BspInfo', 'CalcInfo', 'BaseInfo']:
        if key in data and data[key]:
            sections.append(key)
    
    note = f"OpenStatus={open_status}" + (f" [停牌]" if open_status == 8 else "")
    print(f"[{i:2d}/{TOTAL}] {code} {name:6s} | POST: {status} | 数据段: {','.join(sections)} | {note}")
    results.append({"code": code, "name": name, "status": status, "sections": sections})

print(f"\n{'='*60}")
print(f"汇总: 成功 {success_count}/{TOTAL}, 失败 {fail_count}/{TOTAL}")

if fail_count > 0:
    print("失败股票:")
    for r in results:
        if r['status'] == 'FAIL':
            print(f"  - {r['code']} {r['name']}")

# Verify data completeness
all_complete = True
for r in results:
    if len(r['sections']) < 6:
        print(f"  WARN: {r['code']} {r['name']} 缺少数据段 (实际{len(r['sections'])}/6)")
        all_complete = False
if all_complete:
    print("所有股票HQInfo/ExtInfo/ProInfo/BspInfo/CalcInfo/BaseInfo完整!")
else:
    print(f"[WARN] 部分股票数据不完整")

sys.exit(0 if fail_count == 0 else 1)
